/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class ReleasesUnitTest {

  @Test
  @DisplayName("Numeric versions are ordered part by part, with or without v, of any length")
  void numeric() {
    Assertions.assertTrue(Releases.isAfter("1.4.10", "1.4.9"));
    Assertions.assertTrue(Releases.isAfter("v2.0", "1.9.9"));
    Assertions.assertTrue(Releases.isAfter("2026.11.12", "2026.11.2"));
    Assertions.assertFalse(Releases.isAfter("1.4.2", "1.4.2"));
    Assertions.assertFalse(Releases.isAfter("1.4", "1.4.0"));
    Assertions.assertFalse(Releases.isAfter("1.4.1", "1.4.2"));
  }

  @Test
  @DisplayName("A pre-release goes before its release; the build metadata is ignored")
  void preRelease() {
    Assertions.assertTrue(Releases.isAfter("1.0.0", "1.0.0-SNAPSHOT"));
    Assertions.assertFalse(Releases.isAfter("1.0.0-SNAPSHOT", "1.0.0"));
    Assertions.assertTrue(Releases.isAfter("1.0.0-rc.2", "1.0.0-rc.1"));
    Assertions.assertFalse(Releases.isAfter("1.0.0+build.7", "1.0.0+build.3"));
  }

  @Test
  @DisplayName("Versions without order (hashes) are only equal or different; unknown counts as later")
  void unordered() {
    Assertions.assertFalse(Releases.isAfter("a1b2c3d", "a1b2c3d"));
    Assertions.assertTrue(Releases.isAfter("e4f5a6b", "a1b2c3d"));
    Assertions.assertTrue(Releases.isAfter(null, "1.0.0"));
    Assertions.assertTrue(Releases.isAfter("1.0.0", null));
  }
}
